-- Transactional publication of two original dessert groups after merged-source and public-media verification.
BEGIN;
DO $publish$
DECLARE
 bundles jsonb := $content$[[{"language":"es","slug":"manjar-blanco-del-valle","title":"Manjar blanco del Valle","seo":{"title":"Manjar blanco del Valle","description":"Manjar blanco del Valle con leche, azúcar y arroz. Aprende el punto de la olla y la prueba en plato frío para lograr su textura espesa tradicional.","faq":[{"q":"¿Cuál es el punto exacto del manjar?","a":"Debe desprenderse de la olla, dejar un surco visible 2–3 segundos y mantener un pequeño montículo en un plato frío tras 1 minuto. El tiempo por sí solo no determina el punto."},{"q":"¿Es igual al arequipe?","a":"No. Esta preparación del Valle incorpora arroz remojado y molido, que aporta una textura más firme; el arequipe se elabora normalmente sin arroz."},{"q":"¿Puedo bajar el fuego al final?","a":"Sí. Mantén fuego bajo y movimiento constante, especialmente cuando empiece a despegarse, para que el fondo no se queme."}],"author":"Néstor Bastidas","image_alt":"Manjar blanco del Valle","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"El manjar blanco vallecaucano concentra leche, azúcar y arroz hasta formar un dulce espeso y de color beige. En diciembre acompaña los buñuelos y la natilla; el arroz lo distingue del arequipe.","ingredients":[{"amount":"2000","unit":"ml","name":"leche entera pasteurizada"},{"amount":"400","unit":"g","name":"azúcar blanca"},{"amount":"50","unit":"g","name":"arroz blanco crudo, lavado"},{"amount":"300","unit":"ml","name":"agua para remojar el arroz"}],"steps":[{"title":"Remoja el arroz","content":"Remoja los 50 g de arroz en los 300 ml de agua durante 8 horas en nevera a 4 °C o menos."},{"title":"Licúa el arroz","content":"Licúa el arroz escurrido con 250 ml de la leche durante 2 minutos, hasta obtener una mezcla muy fina. El agua de remojo se desecha."},{"title":"Cuela la mezcla","content":"Pasa la mezcla por un colador fino sobre una olla ancha de fondo grueso; presiona suavemente para extraer el líquido y desecha el residuo grueso.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Cuela la mezcla"},{"title":"Mezcla los ingredientes","content":"Mezcla el colado con los 1750 ml de leche restantes y los 400 g de azúcar en la olla."},{"title":"Cocina lentamente","content":"Cocina destapado a fuego bajo durante 150–180 minutos, con hervor suave y revolviendo sin parar por el fondo y los bordes, hasta que tome color beige y espese.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Cocina lentamente"},{"title":"Comprueba el punto","content":"El manjar está listo cuando se despega de la olla y la cuchara deja el fondo visible 2–3 segundos. Una cucharadita en un plato frío debe mantener su forma tras 1 minuto; si se extiende, continúa la cocción.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Comprueba el punto"},{"title":"Reparte el manjar","content":"Reparte el manjar caliente en recipientes bajos resistentes al calor en cuanto alcance el punto. El dulce se afirma más al enfriarse.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Reparte el manjar"},{"title":"Enfría el manjar","content":"Enfría en recipientes poco profundos y refrigera antes de que pasen 2 horas. Déjalo 4 horas en nevera a 4 °C o menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Enfría el manjar"},{"title":"Sirve","content":"Sirve 1 de las 20 porciones, solo o junto a buñuelos y natilla en la mesa de diciembre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Sirve"}],"notes":"<p>Usa una olla ancha de acero inoxidable de 5–6 litros y una cuchara larga; evita salpicaduras del dulce caliente. Al nivel del mar el hervor empieza cerca de 100 °C y su temperatura aumenta al concentrarse; en altura cambia, por eso el punto se confirma con la olla y el plato frío. Conserva tapado a 4 °C o menos hasta 5 días. Contiene leche.</p>","category":"Postres","course":"Postres","cuisine":"Colombiana","difficulty":"Intermedia","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"El manjar blanco vallecaucano concentra leche, azúcar y arroz hasta formar un dulce espeso y de color beige. En diciembre acompaña los buñuelos y la natilla; el arroz lo distingue del arequipe.","content_html":"","keywords":["Manjar blanco del Valle"],"gallery":[],"public_path":"/manjar-blanco-del-valle","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Suma de nutrientes de los ingredientes dividida entre las raciones; estimación con perfiles USDA.","note":"Por 1 de 20 porciones, sin buñuelos ni natilla. Se calcula toda la leche y el arroz crudo: descartar el residuo del colado puede reducir ligeramente los valores."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"en","slug":"colombian-manjar-blanco","title":"Colombian Manjar Blanco","seo":{"title":"Colombian Manjar Blanco","description":"Make Colombian manjar blanco with milk, sugar and rice. Learn the pan and cold-plate tests for a thick, smooth dessert from the Valle del Cauca.","faq":[{"q":"How do I know it has reached the right point?","a":"It should pull away from the pan, leave a clear trail for 2–3 seconds and hold a small mound on a cold plate after 1 minute. Time alone is not a reliable guide."},{"q":"Is it the same as dulce de leche?","a":"No. This Valle-style version includes soaked, finely ground rice for a firmer texture; dulce de leche is usually made without rice."},{"q":"Can I lower the heat near the end?","a":"Yes. Keep the heat low and stir continuously, especially once the mixture starts pulling away, to prevent scorching."}],"author":"Néstor Bastidas","image_alt":"Colombian Manjar Blanco","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"Manjar blanco from Colombia’s Valle del Cauca is milk, sugar and rice slowly reduced to a thick beige sweet. It joins buñuelos and natilla on December tables; rice sets it apart from dulce de leche.","ingredients":[{"amount":"2000","unit":"ml","name":"pasteurized whole milk"},{"amount":"400","unit":"g","name":"white granulated sugar"},{"amount":"50","unit":"g","name":"uncooked white rice, rinsed"},{"amount":"300","unit":"ml","name":"water for soaking the rice"}],"steps":[{"title":"Soak the rice","content":"Soak the 50 g rice in the 300 ml water for 8 hours in the refrigerator at 4 °C or below."},{"title":"Blend the rice","content":"Blend the drained rice with 250 ml of the milk for 2 minutes, until very fine. Discard the soaking water."},{"title":"Strain the mixture","content":"Strain through a fine sieve into a wide heavy-bottomed pot, pressing gently to collect the liquid; discard the coarse residue.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Strain the mixture"},{"title":"Combine the ingredients","content":"Combine the strained liquid with the remaining 1750 ml milk and 400 g sugar in the pot."},{"title":"Cook slowly","content":"Cook uncovered over low heat for 150–180 minutes at a gentle simmer, stirring the bottom and sides continuously until thick and beige.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Cook slowly"},{"title":"Check the setting point","content":"The mixture is ready when it pulls away from the pan and a spoon leaves the bottom visible for 2–3 seconds. A teaspoon on a cold plate should hold its shape after 1 minute; if it spreads, keep cooking.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Check the setting point"},{"title":"Portion the manjar","content":"Portion the hot manjar into shallow heatproof containers as soon as it reaches the setting point. It firms up further as it cools.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Portion the manjar"},{"title":"Cool the manjar","content":"Cool in shallow containers and refrigerate within 2 hours. Chill for 4 hours at 4 °C or below.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Cool the manjar"},{"title":"Serve","content":"Serve 1 of the 20 portions on its own or with buñuelos and Colombian natilla for a December celebration.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Serve"}],"notes":"<p>Use a wide 5–6 liter stainless-steel pot and a long spoon, taking care with hot splashes. At sea level simmering begins near 100 °C and the temperature rises as the mixture concentrates; altitude changes this, so judge the finish with the pan and cold-plate tests. Keep covered at 4 °C or below for up to 5 days. Contains milk.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombian","difficulty":"Medium","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"Manjar blanco from Colombia’s Valle del Cauca is milk, sugar and rice slowly reduced to a thick beige sweet. It joins buñuelos and natilla on December tables; rice sets it apart from dulce de leche.","content_html":"","keywords":["Colombian Manjar Blanco"],"gallery":[],"public_path":"/en/colombian-manjar-blanco","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Ingredient nutrients summed and divided by servings; estimated using USDA food profiles.","note":"Per 1 of 20 portions, without buñuelos or natilla. All milk and raw rice are counted; discarding strained rice residue may slightly reduce the values."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"de","slug":"kolumbianisches-manjar-blanco","title":"Manjar blanco aus Kolumbien","seo":{"title":"Manjar blanco aus Kolumbien","description":"Manjar blanco aus dem Valle del Cauca mit Milch, Zucker und Reis: mit klarer Garzeit, Topfprobe und Tellerprobe für die richtige feste Konsistenz.","faq":[{"q":"Woran erkenne ich den richtigen Punkt?","a":"Die Masse löst sich vom Topf, die Spur bleibt 2–3 Sekunden offen und eine kleine Portion hält nach 1 Minute auf einem kalten Teller ihre Form. Die Garzeit allein reicht als Kriterium nicht aus."},{"q":"Ist das Dulce de leche?","a":"Nein. Die Variante aus dem Valle enthält eingeweichten, fein gemahlenen Reis und wird dadurch fester. Dulce de leche wird üblicherweise ohne Reis zubereitet."},{"q":"Darf ich die Hitze zum Schluss reduzieren?","a":"Ja. Kleine Hitze und ständiges Rühren sind gerade am Ende wichtig, damit die Masse nicht anbrennt."}],"author":"Néstor Bastidas","image_alt":"Manjar blanco aus Kolumbien","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"Dieses Manjar blanco aus dem kolumbianischen Valle del Cauca entsteht aus langsam eingekochter Milch, Zucker und Reis. Im Dezember begleitet es Buñuelos und Natilla; der Reis unterscheidet es von Dulce de leche.","ingredients":[{"amount":"2000","unit":"ml","name":"pasteurisierte Vollmilch"},{"amount":"400","unit":"g","name":"weißer Zucker"},{"amount":"50","unit":"g","name":"weißer Reis, ungekocht und gewaschen"},{"amount":"300","unit":"ml","name":"Wasser zum Einweichen des Reises"}],"steps":[{"title":"Reis einweichen","content":"Die 50 g Reis in den 300 ml Wasser 8 Stunden im Kühlschrank bei höchstens 4 °C einweichen."},{"title":"Reis pürieren","content":"Den abgetropften Reis mit 250 ml der Milch 2 Minuten sehr fein pürieren. Das Einweichwasser wird nicht verwendet."},{"title":"Mischung sieben","content":"Durch ein feines Sieb in einen breiten Topf mit dickem Boden geben, dabei leicht ausdrücken; grobe Rückstände verwerfen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Mischung sieben"},{"title":"Zutaten mischen","content":"Die gesiebte Flüssigkeit mit den übrigen 1750 ml Milch und 400 g Zucker im Topf mischen."},{"title":"Langsam einkochen","content":"Offen bei kleiner Hitze 150–180 Minuten sanft köcheln, dabei Boden und Seiten ununterbrochen rühren, bis die Masse beige und dick wird.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Langsam einkochen"},{"title":"Konsistenz prüfen","content":"Die Masse ist fertig, wenn sie sich vom Topf löst und eine Löffelspur den Boden 2–3 Sekunden freilegt. Ein Teelöffel auf einem kalten Teller soll nach 1 Minute seine Form behalten; sonst weitergaren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Konsistenz prüfen"},{"title":"Manjar portionieren","content":"Das heiße Manjar sofort nach Erreichen des richtigen Punktes in flache hitzefeste Gefäße füllen. Beim Abkühlen wird es noch fester.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Manjar portionieren"},{"title":"Manjar abkühlen","content":"In flachen Gefäßen abkühlen und innerhalb von 2 Stunden in den Kühlschrank stellen. Dort 4 Stunden bei höchstens 4 °C kühlen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Manjar abkühlen"},{"title":"Servieren","content":"Eine der 20 Portionen pur oder im Dezember mit Buñuelos und kolumbianischer Natilla servieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Servieren"}],"notes":"<p>Einen breiten Edelstahltopf mit 5–6 Litern Inhalt und einen langen Löffel verwenden; heiße Spritzer vermeiden. Auf Meereshöhe beginnt das Köcheln nahe 100 °C, beim Eindicken steigt die Temperatur. In Höhenlagen gelten andere Werte, daher mit Topf- und Tellerprobe prüfen. Zugedeckt bei höchstens 4 °C bis zu 5 Tage lagern. Enthält Milch.</p>","category":"Desserts","course":"Desserts","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"Dieses Manjar blanco aus dem kolumbianischen Valle del Cauca entsteht aus langsam eingekochter Milch, Zucker und Reis. Im Dezember begleitet es Buñuelos und Natilla; der Reis unterscheidet es von Dulce de leche.","content_html":"","keywords":["Manjar blanco aus Kolumbien"],"gallery":[],"public_path":"/de/kolumbianisches-manjar-blanco","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Nährstoffe der Zutaten addiert und durch die Portionen geteilt; Schätzung mit USDA-Lebensmittelwerten.","note":"Für 1 von 20 Portionen, ohne Buñuelos und Natilla. Die gesamte Milch und der rohe Reis sind berechnet; ausgesiebte Reisreste können die Werte leicht verringern."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"fr","slug":"manjar-blanco-colombien","title":"Manjar blanco du Valle","seo":{"title":"Manjar blanco du Valle","description":"Préparez le manjar blanco colombien avec lait, sucre et riz. Repérez le bon point de cuisson grâce au fond de la casserole et au test sur assiette froide.","faq":[{"q":"Comment reconnaître le point exact ?","a":"La pâte se détache, la trace reste ouverte 2–3 secondes et une petite portion garde sa forme sur une assiette froide après 1 minute. Le temps seul ne suffit pas."},{"q":"Est-ce du dulce de leche ?","a":"Non. Cette version du Valle contient du riz trempé et finement moulu, qui lui donne une texture plus ferme. Le dulce de leche se prépare généralement sans riz."},{"q":"Peut-on baisser le feu à la fin ?","a":"Oui. Gardez un feu doux et remuez constamment, surtout lorsque la pâte commence à se détacher, pour éviter qu’elle attache."}],"author":"Néstor Bastidas","image_alt":"Manjar blanco du Valle","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"Le manjar blanco du Valle del Cauca se prépare en faisant réduire lait, sucre et riz jusqu’à obtenir une pâte beige et épaisse. En décembre, il accompagne buñuelos et natilla ; le riz le distingue du dulce de leche.","ingredients":[{"amount":"2000","unit":"ml","name":"lait entier pasteurisé"},{"amount":"400","unit":"g","name":"sucre blanc"},{"amount":"50","unit":"g","name":"riz blanc cru, rincé"},{"amount":"300","unit":"ml","name":"eau pour faire tremper le riz"}],"steps":[{"title":"Faites tremper le riz","content":"Faites tremper les 50 g de riz dans les 300 ml d’eau pendant 8 heures au réfrigérateur à 4 °C maximum."},{"title":"Mixez le riz","content":"Mixez le riz égoutté avec 250 ml du lait pendant 2 minutes, jusqu’à obtenir une texture très fine. L’eau de trempage est jetée."},{"title":"Filtrez le mélange","content":"Filtrez dans une passoire fine au-dessus d’une casserole large à fond épais, en pressant doucement ; jetez les résidus grossiers.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Filtrez le mélange"},{"title":"Mélangez les ingrédients","content":"Mélangez le liquide filtré avec les 1750 ml de lait restants et les 400 g de sucre dans la casserole."},{"title":"Faites réduire doucement","content":"Cuisez à découvert et à feu doux 150–180 minutes, à petits frémissements, en remuant sans arrêt le fond et les bords, jusqu’à épaississement et coloration beige.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Faites réduire doucement"},{"title":"Vérifiez le point","content":"Le mélange est prêt lorsqu’il se détache de la casserole et laisse le fond visible 2–3 secondes après le passage de la cuillère. Une cuillerée sur une assiette froide doit garder sa forme après 1 minute ; sinon, poursuivez la cuisson.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Vérifiez le point"},{"title":"Répartissez le manjar","content":"Répartissez le manjar chaud dans des récipients bas résistants à la chaleur dès que le point est atteint. Il raffermit encore en refroidissant.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Répartissez le manjar"},{"title":"Faites refroidir","content":"Faites refroidir dans des récipients peu profonds et réfrigérez avant 2 heures. Laissez 4 heures au réfrigérateur à 4 °C maximum.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Faites refroidir"},{"title":"Servez","content":"Servez une des 20 portions seule ou avec buñuelos et natilla colombienne pour les fêtes de décembre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Servez"}],"notes":"<p>Utilisez une casserole large en inox de 5–6 litres et une longue cuillère ; attention aux éclaboussures chaudes. Au niveau de la mer, le frémissement commence vers 100 °C puis la température monte avec la concentration. L’altitude modifie ces valeurs : les tests dans la casserole et sur assiette froide font foi. Gardez couvert à 4 °C maximum jusqu’à 5 jours. Contient du lait.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"Le manjar blanco du Valle del Cauca se prépare en faisant réduire lait, sucre et riz jusqu’à obtenir une pâte beige et épaisse. En décembre, il accompagne buñuelos et natilla ; le riz le distingue du dulce de leche.","content_html":"","keywords":["Manjar blanco du Valle"],"gallery":[],"public_path":"/fr/manjar-blanco-colombien","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Nutriments des ingrédients additionnés puis divisés par les portions ; estimation à partir des profils USDA.","note":"Pour 1 portion sur 20, sans buñuelos ni natilla. Tout le lait et le riz cru sont comptés ; les résidus de riz filtrés peuvent réduire légèrement les valeurs."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"it","slug":"manjar-blanco-colombiano","title":"Manjar blanco colombiano","seo":{"title":"Manjar blanco colombiano","description":"Prepara il manjar blanco del Valle con latte, zucchero e riso. Scopri il punto giusto con la prova della pentola e del piattino freddo, senza grumi.","faq":[{"q":"Come riconosco il punto esatto?","a":"Il composto si stacca, il solco resta aperto per 2–3 secondi e una piccola porzione mantiene la forma sul piattino freddo dopo 1 minuto. Il tempo da solo non basta."},{"q":"È uguale al dulce de leche?","a":"No. Questa versione del Valle contiene riso ammollato e finemente macinato, che rende la consistenza più soda. Il dulce de leche di solito non contiene riso."},{"q":"Posso abbassare il fuoco alla fine?","a":"Sì. Mantieni il fuoco basso e mescola continuamente, soprattutto quando il composto comincia a staccarsi, per evitare che bruci."}],"author":"Néstor Bastidas","image_alt":"Manjar blanco colombiano","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"Il manjar blanco del Valle del Cauca nasce dalla lenta riduzione di latte, zucchero e riso fino a una crema beige molto densa. A dicembre si accompagna a buñuelos e natilla; il riso lo distingue dal dulce de leche.","ingredients":[{"amount":"2000","unit":"ml","name":"latte intero pastorizzato"},{"amount":"400","unit":"g","name":"zucchero bianco"},{"amount":"50","unit":"g","name":"riso bianco crudo, sciacquato"},{"amount":"300","unit":"ml","name":"acqua per l’ammollo del riso"}],"steps":[{"title":"Metti in ammollo il riso","content":"Lascia i 50 g di riso nei 300 ml d’acqua per 8 ore in frigorifero a 4 °C o meno."},{"title":"Frulla il riso","content":"Frulla il riso scolato con 250 ml del latte per 2 minuti, fino a renderlo finissimo. L’acqua di ammollo va eliminata."},{"title":"Filtra il composto","content":"Filtra con un colino fine sopra una pentola larga a fondo spesso, premendo delicatamente; elimina i residui grossolani.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Filtra il composto"},{"title":"Mescola gli ingredienti","content":"Mescola il liquido filtrato con i restanti 1750 ml di latte e i 400 g di zucchero nella pentola."},{"title":"Cuoci lentamente","content":"Cuoci scoperto a fuoco basso per 150–180 minuti, a leggero bollore, mescolando senza fermarti sul fondo e sui bordi finché il composto diventa denso e beige.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Cuoci lentamente"},{"title":"Controlla il punto","content":"È pronto quando si stacca dalla pentola e il passaggio del cucchiaio lascia il fondo visibile per 2–3 secondi. Un cucchiaino su un piattino freddo deve mantenere la forma dopo 1 minuto; altrimenti continua la cottura.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Controlla il punto"},{"title":"Distribuisci il manjar","content":"Distribuisci subito il manjar caldo in contenitori bassi resistenti al calore quando raggiunge il punto. Raffreddandosi diventerà ancora più sodo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Distribuisci il manjar"},{"title":"Fai raffreddare","content":"Fai raffreddare in contenitori bassi e metti in frigorifero entro 2 ore. Lascia 4 ore a 4 °C o meno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Fai raffreddare"},{"title":"Servi","content":"Servi una delle 20 porzioni da sola o con buñuelos e natilla colombiana per le feste di dicembre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Servi"}],"notes":"<p>Usa una pentola larga in acciaio da 5–6 litri e un cucchiaio lungo, facendo attenzione agli schizzi caldi. Al livello del mare il bollore inizia vicino a 100 °C e la temperatura aumenta con la concentrazione. In quota cambia: verifica il punto con pentola e piattino freddo. Conserva coperto a 4 °C o meno fino a 5 giorni. Contiene latte.</p>","category":"Dolci","course":"Dolci","cuisine":"Colombiana","difficulty":"Media","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"Il manjar blanco del Valle del Cauca nasce dalla lenta riduzione di latte, zucchero e riso fino a una crema beige molto densa. A dicembre si accompagna a buñuelos e natilla; il riso lo distingue dal dulce de leche.","content_html":"","keywords":["Manjar blanco colombiano"],"gallery":[],"public_path":"/it/manjar-blanco-colombiano","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Somma dei nutrienti degli ingredienti divisa per le porzioni; stima basata su profili USDA.","note":"Per 1 delle 20 porzioni, senza buñuelos o natilla. Sono conteggiati tutto il latte e il riso crudo; lo scarto filtrato può ridurre leggermente i valori."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"ja","slug":"colombia-manjar-blanco","title":"コロンビアのマンハル・ブランコ","seo":{"title":"コロンビアのマンハル・ブランコ","description":"コロンビアのバジェ地方に伝わるマンハル・ブランコ。牛乳、砂糖、米を弱火で混ぜ続け、なめらかで濃厚なお菓子に仕上げます。鍋底に残る筋と冷たい皿を使って、火から下ろすちょうどよいタイミングを確認。米の下ごしらえ、加熱時間、冷やし方まで紹介する20人分のレシピです。","faq":[{"q":"火から下ろすタイミングは？","a":"生地が鍋から離れ、筋が2〜3秒残り、冷たい皿にのせた少量が1分後も小さな山の形を保つことが目安です。時間だけでは判断しません。"},{"q":"ドゥルセ・デ・レチェと同じですか？","a":"異なります。バジェ地方のこの作り方は浸して細かくした米を使うため、しっかりした食感になります。ドゥルセ・デ・レチェは通常、米を使いません。"},{"q":"最後に火を弱めてもよいですか？","a":"はい。特に生地が鍋から離れ始めたら、弱火で絶えず混ぜ、焦げ付きを防ぎます。"}],"author":"Néstor Bastidas","image_alt":"コロンビアのマンハル・ブランコ","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"マンハル・ブランコは、コロンビアのバジェ・デル・カウカ地方で親しまれる、牛乳と砂糖、米を煮詰めた濃厚なミルク菓子。12月にはブニュエロやナティージャと並びます。米を使う点がドゥルセ・デ・レチェとの違いです。","ingredients":[{"amount":"2000","unit":"ml","name":"成分無調整の全脂牛乳（殺菌済み）"},{"amount":"400","unit":"g","name":"白砂糖"},{"amount":"50","unit":"g","name":"白米（乾燥重量、洗ったもの）"},{"amount":"300","unit":"ml","name":"米を浸す水"}],"steps":[{"title":"米を浸す","content":"米50 gを水300 mlに入れ、4 °C以下の冷蔵庫で8時間浸します。"},{"title":"米をかくはんする","content":"水を切った米と分量の牛乳250 mlをミキサーで2分かくはんし、細かくします。浸していた水は使いません。"},{"title":"混合液をこす","content":"厚底の広い鍋に目の細かいざるを重ね、混合液を軽く押しながらこします。粗い残りは取り除きます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"混合液をこす"},{"title":"材料を混ぜる","content":"こした液体に残りの牛乳1750 mlと砂糖400 gを混ぜます。"},{"title":"ゆっくり煮詰める","content":"ふたをせず、弱火で150〜180分静かに煮ます。鍋底と側面を休まず混ぜ、ベージュ色で濃厚な状態にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"ゆっくり煮詰める"},{"title":"仕上がりを確かめる","content":"生地が鍋から離れ、へらの筋から鍋底が2〜3秒見えれば仕上がりの目安です。冷たい皿に小さじ1杯のせ、1分後も形を保つことを確認します。広がる場合は煮詰め続けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"仕上がりを確かめる"},{"title":"器に分ける","content":"仕上がったら熱いうちに浅い耐熱容器に分けます。冷めるとさらに固くなります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"器に分ける"},{"title":"冷やす","content":"浅い容器で粗熱を取り、2時間以内に冷蔵します。4 °C以下の冷蔵庫で4時間冷やします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"冷やす"},{"title":"盛り付ける","content":"20人分のうち1人分を盛り付けます。そのままでも、12月の食卓でブニュエロやナティージャに添えても楽しめます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"盛り付ける"}],"notes":"<p>容量5〜6リットルの広いステンレス鍋と長いへらを使い、熱いはねに注意します。海面付近では約100 °Cで沸き始め、煮詰まると温度が上がります。標高によって変わるため、鍋底と冷たい皿で仕上がりを判断してください。ふたをして4 °C以下で保存し、5日以内に食べ切ります。乳成分を含みます。</p>","category":"デザート","course":"デザート","cuisine":"コロンビア料理","difficulty":"中級","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"マンハル・ブランコは、コロンビアのバジェ・デル・カウカ地方で親しまれる、牛乳と砂糖、米を煮詰めた濃厚なミルク菓子。12月にはブニュエロやナティージャと並びます。米を使う点がドゥルセ・デ・レチェとの違いです。","content_html":"","keywords":["コロンビアのマンハル・ブランコ"],"gallery":[],"public_path":"/ja/colombia-manjar-blanco","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"USDAの食品成分値から材料全量の栄養を合計し、人数分で割った推定値です。","note":"全20等分の1個分。ブニュエロとナティージャは含みません。牛乳と生米の全量を計算しているため、こした米の残りを捨てると実際の値はやや少なくなる場合があります。"},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"},{"language":"pt","slug":"manjar-blanco-colombiano","title":"Manjar blanco colombiano","seo":{"title":"Manjar blanco colombiano","description":"Faça o manjar blanco do Valle com leite, açúcar e arroz. Aprenda a reconhecer o ponto no fundo da panela e no prato frio para uma textura firme.","faq":[{"q":"Como reconhecer o ponto exato?","a":"O doce desgruda da panela, o caminho fica aberto por 2–3 segundos e uma pequena porção mantém um montinho no prato frio após 1 minuto. O tempo sozinho não define o ponto."},{"q":"É igual ao doce de leite?","a":"Não. Esta versão do Valle leva arroz demolhado e finamente moído, que dá uma textura mais firme. O doce de leite normalmente não leva arroz."},{"q":"Posso baixar o fogo no final?","a":"Sim. Mantenha fogo baixo e mexa sem parar, principalmente quando o doce começar a desgrudar, para não queimar o fundo."}],"author":"Néstor Bastidas","image_alt":"Manjar blanco colombiano","additional_time_minutes":720,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada-16x9.webp"]},"summary":"O manjar blanco do Valle del Cauca é um doce bege e espesso feito com leite, açúcar e arroz, cozidos lentamente. Em dezembro acompanha buñuelos e natilla; não é o manjar brasileiro de coco, e o arroz o diferencia do doce de leite.","ingredients":[{"amount":"2000","unit":"ml","name":"leite integral pasteurizado"},{"amount":"400","unit":"g","name":"açúcar branco"},{"amount":"50","unit":"g","name":"arroz branco cru, lavado"},{"amount":"300","unit":"ml","name":"água para deixar o arroz de molho"}],"steps":[{"title":"Deixe o arroz de molho","content":"Deixe os 50 g de arroz nos 300 ml de água por 8 horas na geladeira a 4 °C ou menos."},{"title":"Bata o arroz","content":"Bata o arroz escorrido com 250 ml do leite por 2 minutos, até ficar bem fino. Descarte a água do molho."},{"title":"Coe a mistura","content":"Coe numa peneira fina sobre uma panela larga de fundo grosso, pressionando levemente para extrair o líquido; descarte o resíduo grosso.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-03.webp","image_alt":"Coe a mistura"},{"title":"Misture os ingredientes","content":"Misture o líquido coado com os 1750 ml restantes de leite e os 400 g de açúcar na panela."},{"title":"Cozinhe lentamente","content":"Cozinhe destampado em fogo baixo por 150–180 minutos, com fervura suave, mexendo sem parar no fundo e nas laterais até engrossar e ficar bege.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-05.webp","image_alt":"Cozinhe lentamente"},{"title":"Confira o ponto","content":"Está pronto quando desgruda da panela e a colher deixa o fundo visível por 2–3 segundos. Uma colher de chá num prato frio deve manter a forma após 1 minuto; se espalhar, continue cozinhando.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-06.webp","image_alt":"Confira o ponto"},{"title":"Distribua o manjar","content":"Distribua o manjar quente em recipientes baixos resistentes ao calor assim que atingir o ponto. O doce firma mais ao esfriar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-07.webp","image_alt":"Distribua o manjar"},{"title":"Esfrie o manjar","content":"Esfrie em recipientes rasos e leve à geladeira em até 2 horas. Deixe por 4 horas a 4 °C ou menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/paso-08.webp","image_alt":"Esfrie o manjar"},{"title":"Sirva","content":"Sirva uma das 20 porções pura ou com buñuelos e natilla colombiana na mesa de dezembro.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp","image_alt":"Sirva"}],"notes":"<p>Use uma panela larga de inox de 5–6 litros e uma colher longa, com cuidado com os respingos quentes. Ao nível do mar a fervura começa perto de 100 °C e a temperatura sobe com a concentração; em altitude, os valores mudam. Por isso, confirme o ponto com a panela e o prato frio. Conserve tampado a 4 °C ou menos por até 5 dias. Contém leite.</p>","category":"Sobremesas","course":"Sobremesas","cuisine":"Colombiana","difficulty":"Média","servings":20,"prep_time_minutes":20,"cook_time_minutes":165,"total_time_minutes":905,"excerpt":"O manjar blanco do Valle del Cauca é um doce bege e espesso feito com leite, açúcar e arroz, cozidos lentamente. Em dezembro acompanha buñuelos e natilla; não é o manjar brasileiro de coco, e o arroz o diferencia do doce de leite.","content_html":"","keywords":["Manjar blanco colombiano"],"gallery":[],"public_path":"/pt/manjar-blanco-colombiano","nutrition":{"calories":149.4,"protein_g":3.4,"carbs_g":26.9,"fat_g":3.4,"serving_size":"1/20","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Soma dos nutrientes dos ingredientes dividida pelas porções; estimativa com perfis de alimentos do USDA.","note":"Por 1 das 20 porções, sem buñuelos nem natilla. Todo o leite e o arroz cru entram no cálculo; o resíduo coado e descartado pode reduzir um pouco os valores."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/manjar-blanco-del-valle/portada.webp"}],[{"language":"es","slug":"dulce-de-breva","title":"Dulce de breva en almíbar","seo":{"title":"Dulce de breva en almíbar","description":"Brevas enteras en almíbar de panela con canela y clavo, servidas con arequipe y queso fresco. Un dulce colombiano distinto de la mermelada de higos.","faq":[{"q":"¿En qué se diferencia de la mermelada de higos?","a":"Las brevas se mantienen enteras y se sirven en almíbar de panela. La mermelada se elabora con fruta troceada o triturada y se usa para untar; son recetas distintas."},{"q":"¿Por qué se cuecen primero sin panela?","a":"El primer hervor ablanda la fruta. Añadirla ya tierna al almíbar ayuda a conservar la pieza entera sin dejar un centro duro."},{"q":"¿Qué hago si el almíbar espesa antes de que estén tiernas?","a":"Añade agua caliente en pequeñas cantidades y continúa a fuego bajo hasta que una brocheta entre con facilidad, sin remover con fuerza."}],"author":"Néstor Bastidas","image_alt":"Dulce de breva en almíbar","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"Este dulce colombiano conserva las brevas enteras, tiernas y brillantes, dentro de un almíbar de panela, canela y clavo. Se sirve con arequipe y queso fresco; aquí la fruta no se tritura ni se convierte en mermelada.","ingredients":[{"amount":"600","unit":"g","name":"brevas verdes firmes, unas 12 piezas comestibles"},{"amount":"400","unit":"g","name":"panela rallada"},{"amount":"1000","unit":"ml","name":"agua para el almíbar"},{"amount":"1500","unit":"ml","name":"agua para ablandar las brevas"},{"amount":"2","unit":"g","name":"bicarbonato de sodio alimentario"},{"amount":"1","unit":"unidad","name":"canela en rama, unos 3 g"},{"amount":"4","unit":"unidad","name":"clavos de olor enteros, unos 0,8 g"},{"amount":"120","unit":"g","name":"arequipe"},{"amount":"180","unit":"g","name":"queso fresco pasteurizado"}],"steps":[{"title":"Lava las brevas","content":"Lava los 600 g de brevas bajo agua corriente. Deben estar firmes, sin golpes ni moho; evita las frutas muy maduras y blandas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Lava las brevas"},{"title":"Marca las brevas","content":"Haz una cruz superficial de unos 5 mm en la base de cada breva, sin partirla ni quitarle la forma entera. Recorta solo la punta dura del tallo si sobresale.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Marca las brevas"},{"title":"Ablanda las brevas","content":"Cuece las brevas en los 1500 ml de agua con los 2 g de bicarbonato durante 20–30 minutos desde el hervor suave, hasta que una brocheta entre con facilidad.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Ablanda las brevas"},{"title":"Enjuaga las brevas","content":"Enjuaga las brevas cocidas con agua limpia para retirar el bicarbonato. Deben quedar bien escurridas antes del almíbar."},{"title":"Prepara el almíbar","content":"Disuelve los 400 g de panela en los 1000 ml de agua con la rama de canela y los 4 clavos, a fuego bajo durante unos 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Prepara el almíbar"},{"title":"Cala las brevas","content":"Cocina las brevas enteras en el almíbar, destapadas y a fuego bajo, durante 90–120 minutos. Están listas cuando se ven oscuras y brillantes y el almíbar cubre ligeramente una cuchara; mueve la olla suavemente sin aplastarlas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Cala las brevas"},{"title":"Retira las especias","content":"Retira la canela y los 4 clavos del almíbar al terminar la cocción.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Retira las especias"},{"title":"Enfría el dulce","content":"Enfría las brevas en su almíbar en un recipiente poco profundo durante un máximo de 1 hora y refrigera 4 horas a 4 °C o menos. No las dejes fuera más de 2 horas en total.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Enfría el dulce"},{"title":"Sirve","content":"Sirve 2 brevas por persona con su parte del almíbar, 20 g de arequipe y 30 g de queso fresco. Rinde 6 porciones.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Sirve"}],"notes":"<p>Compra brevas verdes firmes vendidas para consumo, no frutos de plantas ornamentales. La cocción es al fuego, sin horno; el agua hierve cerca de 100 °C al nivel del mar y a menor temperatura en altura. Conserva las piezas enteras durante todo el proceso. Guarda las brevas con su almíbar tapadas a 4 °C o menos hasta 5 días, y añade el queso y el arequipe al servir. Es un postre refrigerado, no una conserva para despensa. Los acompañamientos contienen leche.</p>","category":"Postres","course":"Postres","cuisine":"Colombiana","difficulty":"Intermedia","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"Este dulce colombiano conserva las brevas enteras, tiernas y brillantes, dentro de un almíbar de panela, canela y clavo. Se sirve con arequipe y queso fresco; aquí la fruta no se tritura ni se convierte en mermelada.","content_html":"","keywords":["Dulce de breva en almíbar"],"gallery":[],"public_path":"/dulce-de-breva","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Suma de nutrientes de los ingredientes dividida entre las raciones; estimación con perfiles USDA.","note":"Por 2 brevas con una sexta parte de todo el almíbar, 20 g de arequipe y 30 g de queso fresco. La panela se aproxima con azúcar morena USDA; no incluye especias retiradas ni bicarbonato enjuagado. Si dejas almíbar, consumirás menos azúcar."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"en","slug":"colombian-candied-figs-dulce-de-breva","title":"Colombian Candied Figs","seo":{"title":"Colombian Candied Figs","description":"Whole figs simmered in panela syrup with cinnamon and cloves, served with dulce de leche and fresh cheese. A Colombian dessert, not a fig jam.","faq":[{"q":"How is this different from fig jam?","a":"The figs stay whole and are served in panela syrup. Jam uses chopped or crushed fruit and is intended for spreading; these are different recipes."},{"q":"Why soften the figs before adding panela?","a":"The first simmer softens the fruit. Adding tender figs to the syrup helps preserve their shape without leaving a firm center."},{"q":"What if the syrup thickens before the figs soften?","a":"Add small amounts of hot water and continue over low heat until a skewer slides in easily, without stirring roughly."}],"author":"Néstor Bastidas","image_alt":"Colombian Candied Figs","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"Dulce de breva keeps the figs whole, tender and glossy in a syrup flavored with panela, cinnamon and cloves. Serve with arequipe, the Colombian dulce de leche, and fresh cheese; the fruit is never mashed into jam.","ingredients":[{"amount":"600","unit":"g","name":"firm green edible figs, about 12 fruits"},{"amount":"400","unit":"g","name":"panela, grated"},{"amount":"1000","unit":"ml","name":"water for the syrup"},{"amount":"1500","unit":"ml","name":"water for softening the figs"},{"amount":"2","unit":"g","name":"food-grade baking soda"},{"amount":"1","unit":"piece","name":"cinnamon stick, about 3 g"},{"amount":"4","unit":"piece","name":"whole cloves, about 0.8 g"},{"amount":"120","unit":"g","name":"arequipe or dulce de leche"},{"amount":"180","unit":"g","name":"pasteurized fresh cheese, queso fresco"}],"steps":[{"title":"Wash the figs","content":"Wash the 600 g figs under running water. Choose firm fruit without bruising or mold; avoid very ripe, soft figs.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Wash the figs"},{"title":"Score the figs","content":"Make a shallow cross about 5 mm deep in the base of each fig without splitting it apart. Trim only the hard stem tip if it sticks out.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Score the figs"},{"title":"Soften the figs","content":"Cook the figs in the 1500 ml water with the 2 g baking soda for 20–30 minutes from a gentle boil, until a skewer slides in easily.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Soften the figs"},{"title":"Rinse the figs","content":"Rinse the cooked figs with clean water to remove the baking soda. They should be well drained before going into the syrup."},{"title":"Make the syrup","content":"Dissolve the 400 g panela in the 1000 ml water with the cinnamon stick and 4 cloves over low heat for about 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Make the syrup"},{"title":"Simmer in syrup","content":"Cook the whole figs uncovered in the syrup over low heat for 90–120 minutes. They are ready when dark and glossy and the syrup lightly coats a spoon; gently swirl the pan rather than crushing the fruit.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Simmer in syrup"},{"title":"Remove the spices","content":"Remove the cinnamon stick and all 4 cloves when cooking is complete.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Remove the spices"},{"title":"Chill the dessert","content":"Cool the figs in their syrup in a shallow container for no more than 1 hour, then refrigerate for 4 hours at 4 °C or below. Total time out of the refrigerator must stay under 2 hours.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Chill the dessert"},{"title":"Serve","content":"Serve 2 figs per person with a share of the syrup, 20 g dulce de leche and 30 g fresh cheese. Makes 6 servings.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Serve"}],"notes":"<p>Buy firm green figs sold as food, not fruit from ornamental plants. This is a stovetop recipe; water boils near 100 °C at sea level and at a lower temperature at altitude. Keep the fruit whole throughout. Refrigerate covered in its syrup at 4 °C or below for up to 5 days; add the cheese and dulce de leche when serving. This is a refrigerated dessert, not a shelf-stable preserve. The accompaniments contain milk.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombian","difficulty":"Medium","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"Dulce de breva keeps the figs whole, tender and glossy in a syrup flavored with panela, cinnamon and cloves. Serve with arequipe, the Colombian dulce de leche, and fresh cheese; the fruit is never mashed into jam.","content_html":"","keywords":["Colombian Candied Figs"],"gallery":[],"public_path":"/en/colombian-candied-figs-dulce-de-breva","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Ingredient nutrients summed and divided by servings; estimated using USDA food profiles.","note":"Per 2 figs with one sixth of all the syrup, 20 g dulce de leche and 30 g queso fresco. USDA brown sugar approximates panela; removed spices and rinsed-off baking soda are excluded. Leaving syrup reduces sugar intake."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"de","slug":"kolumbianische-feigen-in-sirup","title":"Kolumbianische Feigen in Sirup","seo":{"title":"Kolumbianische Feigen in Sirup","description":"Ganze Feigen in Panela-Sirup mit Zimt und Nelken, dazu Dulce de leche und Frischkäse. Ein kolumbianisches Dessert, das sich von Feigenmarmelade unterscheidet.","faq":[{"q":"Was unterscheidet das Dessert von Feigenmarmelade?","a":"Die Feigen bleiben ganz und liegen in Panela-Sirup. Marmelade wird aus zerkleinerten Früchten hergestellt und dient als Brotaufstrich; es sind unterschiedliche Rezepte."},{"q":"Warum werden die Feigen zuerst ohne Panela gekocht?","a":"Das erste Garen macht sie weich. Bereits zarte Feigen behalten im Sirup ihre Form und bleiben innen nicht hart."},{"q":"Was tun, wenn der Sirup zu früh eindickt?","a":"Etwas heißes Wasser in kleinen Mengen zugeben und bei kleiner Hitze weitergaren, bis ein Spieß leicht hineingleitet. Nicht kräftig rühren."}],"author":"Néstor Bastidas","image_alt":"Kolumbianische Feigen in Sirup","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"Bei Dulce de breva bleiben die Feigen ganz und werden in einem Sirup aus Panela, Zimt und Nelken weich und glänzend gegart. Dazu passen Arequipe, die kolumbianische Dulce de leche, und frischer Käse. Die Früchte werden nicht zu Marmelade zerdrückt.","ingredients":[{"amount":"600","unit":"g","name":"feste grüne Speisefeigen, etwa 12 Früchte"},{"amount":"400","unit":"g","name":"geriebene Panela, unraffinierter Rohrzucker"},{"amount":"1000","unit":"ml","name":"Wasser für den Sirup"},{"amount":"1500","unit":"ml","name":"Wasser zum Weichkochen der Feigen"},{"amount":"2","unit":"g","name":"lebensmittelechtes Natron"},{"amount":"1","unit":"Stück","name":"Zimtstange, etwa 3 g"},{"amount":"4","unit":"Stück","name":"ganze Gewürznelken, etwa 0,8 g"},{"amount":"120","unit":"g","name":"Arequipe oder Dulce de leche"},{"amount":"180","unit":"g","name":"pasteurisierter frischer Käse, Queso fresco"}],"steps":[{"title":"Feigen waschen","content":"Die 600 g Feigen unter fließendem Wasser waschen. Feste Früchte ohne Druckstellen oder Schimmel verwenden; sehr reife, weiche Früchte vermeiden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Feigen waschen"},{"title":"Feigen einritzen","content":"Am unteren Ende jeder Feige ein etwa 5 mm tiefes Kreuz einritzen, ohne sie zu zerteilen. Nur eine hervorstehende harte Stielspitze kürzen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Feigen einritzen"},{"title":"Feigen weichkochen","content":"Die Feigen in den 1500 ml Wasser mit den 2 g Natron ab dem sanften Aufkochen 20–30 Minuten garen, bis ein Spieß leicht hineingleitet.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Feigen weichkochen"},{"title":"Feigen abspülen","content":"Die gegarten Feigen mit sauberem Wasser abspülen, um das Natron zu entfernen. Vor dem Sirup sollen sie gut abgetropft sein."},{"title":"Sirup zubereiten","content":"Die 400 g Panela in den 1000 ml Wasser mit Zimtstange und 4 Nelken bei kleiner Hitze etwa 10 Minuten auflösen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Sirup zubereiten"},{"title":"Feigen im Sirup garen","content":"Die ganzen Feigen offen bei kleiner Hitze 90–120 Minuten im Sirup garen. Sie sind fertig, wenn sie dunkel glänzen und der Sirup einen Löffel leicht überzieht; den Topf behutsam schwenken, ohne die Früchte zu zerdrücken.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Feigen im Sirup garen"},{"title":"Gewürze entfernen","content":"Nach dem Garen die Zimtstange und alle 4 Nelken herausnehmen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Gewürze entfernen"},{"title":"Dessert kühlen","content":"Die Feigen im Sirup in einem flachen Gefäß höchstens 1 Stunde abkühlen, dann 4 Stunden bei höchstens 4 °C kühlen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Dessert kühlen"},{"title":"Servieren","content":"Je 2 Feigen mit einem Anteil Sirup, 20 g Dulce de leche und 30 g frischem Käse servieren. Ergibt 6 Portionen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Servieren"}],"notes":"<p>Feste grüne Feigen aus dem Lebensmittelhandel verwenden, keine Früchte von Zierpflanzen. Das Dessert wird auf dem Herd zubereitet; Wasser kocht auf Meereshöhe nahe 100 °C und in Höhenlagen früher. Die Früchte bleiben ganz. Zugedeckt im Sirup bei höchstens 4 °C bis zu 5 Tage lagern, Käse und Dulce de leche erst beim Servieren zugeben. Dieses Dessert gehört in den Kühlschrank und ist keine haltbare Vorratskonserve. Die Beilagen enthalten Milch.</p>","category":"Desserts","course":"Desserts","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"Bei Dulce de breva bleiben die Feigen ganz und werden in einem Sirup aus Panela, Zimt und Nelken weich und glänzend gegart. Dazu passen Arequipe, die kolumbianische Dulce de leche, und frischer Käse. Die Früchte werden nicht zu Marmelade zerdrückt.","content_html":"","keywords":["Kolumbianische Feigen in Sirup"],"gallery":[],"public_path":"/de/kolumbianische-feigen-in-sirup","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Nährstoffe der Zutaten addiert und durch die Portionen geteilt; Schätzung mit USDA-Lebensmittelwerten.","note":"Für 2 Feigen mit einem Sechstel des gesamten Sirups, 20 g Dulce de leche und 30 g Queso fresco. USDA-Werte für braunen Zucker nähern Panela an; entfernte Gewürze und abgespültes Natron sind nicht enthalten. Übrig gelassener Sirup senkt die Zuckeraufnahme."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"fr","slug":"figues-confites-colombiennes","title":"Figues confites colombiennes","seo":{"title":"Figues confites colombiennes","description":"Des figues entières au sirop de panela, cannelle et clous de girofle, servies avec dulce de leche et fromage frais. Un dessert différent de la confiture.","faq":[{"q":"Quelle différence avec la confiture de figues ?","a":"Les figues restent entières dans un sirop de panela. La confiture utilise des fruits coupés ou écrasés et se tartine : ce sont deux recettes distinctes."},{"q":"Pourquoi cuire les figues avant la panela ?","a":"La première cuisson les attendrit. Des figues déjà tendres gardent leur forme dans le sirop sans rester dures à cœur."},{"q":"Que faire si le sirop épaissit trop tôt ?","a":"Ajoutez un peu d’eau chaude et poursuivez à feu doux jusqu’à ce qu’une pique entre facilement, sans remuer brutalement."}],"author":"Néstor Bastidas","image_alt":"Figues confites colombiennes","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"Dans le dulce de breva, les figues restent entières et deviennent tendres et brillantes dans un sirop de panela, cannelle et girofle. Elles se servent avec arequipe, le dulce de leche colombien, et fromage frais ; on ne les écrase pas en confiture.","ingredients":[{"amount":"600","unit":"g","name":"figues vertes comestibles et fermes, environ 12 fruits"},{"amount":"400","unit":"g","name":"panela râpée, sucre de canne non raffiné"},{"amount":"1000","unit":"ml","name":"eau pour le sirop"},{"amount":"1500","unit":"ml","name":"eau pour attendrir les figues"},{"amount":"2","unit":"g","name":"bicarbonate de soude alimentaire"},{"amount":"1","unit":"pièce","name":"bâton de cannelle, environ 3 g"},{"amount":"4","unit":"pièce","name":"clous de girofle entiers, environ 0,8 g"},{"amount":"120","unit":"g","name":"arequipe ou dulce de leche"},{"amount":"180","unit":"g","name":"fromage frais pasteurisé de type queso fresco"}],"steps":[{"title":"Lavez les figues","content":"Lavez les 600 g de figues sous l’eau courante. Choisissez des fruits fermes, sans chocs ni moisissure ; évitez les figues très mûres et molles.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Lavez les figues"},{"title":"Incisez les figues","content":"Faites une croix superficielle d’environ 5 mm à la base de chaque figue sans la partager. Raccourcissez seulement la pointe dure de la tige si elle dépasse.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Incisez les figues"},{"title":"Attendrissez les figues","content":"Cuisez les figues dans les 1500 ml d’eau avec les 2 g de bicarbonate pendant 20–30 minutes dès le petit bouillon, jusqu’à ce qu’une pique entre facilement.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Attendrissez les figues"},{"title":"Rincez les figues","content":"Rincez les figues cuites à l’eau propre pour enlever le bicarbonate. Elles doivent être bien égouttées avant le sirop."},{"title":"Préparez le sirop","content":"Faites dissoudre les 400 g de panela dans les 1000 ml d’eau avec la cannelle et les 4 clous de girofle à feu doux pendant environ 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Préparez le sirop"},{"title":"Confisez les figues","content":"Cuisez les figues entières à découvert dans le sirop à feu doux pendant 90–120 minutes. Elles sont prêtes lorsqu’elles deviennent foncées et brillantes et que le sirop nappe légèrement une cuillère ; remuez doucement la casserole sans écraser les fruits.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Confisez les figues"},{"title":"Retirez les épices","content":"Retirez la cannelle et les 4 clous de girofle après la cuisson.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Retirez les épices"},{"title":"Faites refroidir","content":"Laissez refroidir les figues dans leur sirop dans un récipient peu profond pendant 1 heure maximum, puis réfrigérez 4 heures à 4 °C maximum. Ne dépassez pas 2 heures au total hors du réfrigérateur.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Faites refroidir"},{"title":"Servez","content":"Servez 2 figues par personne avec une part du sirop, 20 g de dulce de leche et 30 g de fromage frais. Vous obtenez 6 portions.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Servez"}],"notes":"<p>Achetez des figues vertes fermes destinées à l’alimentation, pas des fruits de plantes ornementales. La recette se prépare sur le feu ; l’eau bout près de 100 °C au niveau de la mer et plus bas en altitude. Gardez les fruits entiers. Conservez-les couverts dans leur sirop à 4 °C maximum jusqu’à 5 jours, et ajoutez fromage et dulce de leche au service. Ce dessert se garde au réfrigérateur, ce n’est pas une conserve de placard. Les accompagnements contiennent du lait.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"Dans le dulce de breva, les figues restent entières et deviennent tendres et brillantes dans un sirop de panela, cannelle et girofle. Elles se servent avec arequipe, le dulce de leche colombien, et fromage frais ; on ne les écrase pas en confiture.","content_html":"","keywords":["Figues confites colombiennes"],"gallery":[],"public_path":"/fr/figues-confites-colombiennes","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Nutriments des ingrédients additionnés puis divisés par les portions ; estimation à partir des profils USDA.","note":"Pour 2 figues avec un sixième de tout le sirop, 20 g de confiture de lait et 30 g de queso fresco. Le sucre brun USDA sert d’équivalent à la panela ; épices retirées et bicarbonate rincé sont exclus. Laisser du sirop réduit le sucre consommé."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"it","slug":"fichi-sciroppati-colombiani","title":"Fichi sciroppati colombiani","seo":{"title":"Fichi sciroppati colombiani","description":"Fichi interi nello sciroppo di panela con cannella e chiodi di garofano, serviti con dulce de leche e formaggio fresco. Diversi dalla confettura di fichi.","faq":[{"q":"Che differenza c’è con la confettura di fichi?","a":"I fichi rimangono interi nello sciroppo di panela. La confettura usa frutta tagliata o schiacciata e si spalma: sono ricette diverse."},{"q":"Perché si cuociono prima senza panela?","a":"La prima cottura ammorbidisce la frutta. Inserire fichi già teneri nello sciroppo mantiene la forma senza lasciare il centro duro."},{"q":"Se lo sciroppo addensa prima che siano teneri?","a":"Aggiungi poca acqua calda per volta e prosegui a fuoco basso finché uno stecchino entra facilmente, senza mescolare energicamente."}],"author":"Néstor Bastidas","image_alt":"Fichi sciroppati colombiani","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"Nel dulce de breva i fichi restano interi e diventano teneri e lucidi nello sciroppo di panela, cannella e chiodi di garofano. Si accompagnano ad arequipe, il dulce de leche colombiano, e formaggio fresco; la frutta non viene ridotta in confettura.","ingredients":[{"amount":"600","unit":"g","name":"fichi verdi sodi e commestibili, circa 12 frutti"},{"amount":"400","unit":"g","name":"panela grattugiata, zucchero di canna non raffinato"},{"amount":"1000","unit":"ml","name":"acqua per lo sciroppo"},{"amount":"1500","unit":"ml","name":"acqua per ammorbidire i fichi"},{"amount":"2","unit":"g","name":"bicarbonato di sodio alimentare"},{"amount":"1","unit":"pezzo","name":"stecca di cannella, circa 3 g"},{"amount":"4","unit":"pezzo","name":"chiodi di garofano interi, circa 0,8 g"},{"amount":"120","unit":"g","name":"arequipe o dulce de leche"},{"amount":"180","unit":"g","name":"formaggio fresco pastorizzato tipo queso fresco"}],"steps":[{"title":"Lava i fichi","content":"Lava i 600 g di fichi sotto acqua corrente. Scegli frutti sodi, senza ammaccature o muffa; evita quelli molto maturi e molli.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Lava i fichi"},{"title":"Incidi i fichi","content":"Incidi una croce superficiale di circa 5 mm alla base di ogni fico, senza dividerlo. Accorcia soltanto la punta dura del picciolo se sporge.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Incidi i fichi"},{"title":"Ammorbidisci i fichi","content":"Cuoci i fichi nei 1500 ml d’acqua con i 2 g di bicarbonato per 20–30 minuti dal leggero bollore, finché uno stecchino entra facilmente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Ammorbidisci i fichi"},{"title":"Sciacqua i fichi","content":"Sciacqua i fichi cotti con acqua pulita per eliminare il bicarbonato. Devono essere ben scolati prima dello sciroppo."},{"title":"Prepara lo sciroppo","content":"Sciogli i 400 g di panela nei 1000 ml d’acqua con la cannella e i 4 chiodi di garofano a fuoco basso per circa 10 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Prepara lo sciroppo"},{"title":"Cuoci nello sciroppo","content":"Cuoci i fichi interi scoperti nello sciroppo a fuoco basso per 90–120 minuti. Sono pronti quando diventano scuri e lucidi e lo sciroppo vela leggermente un cucchiaio; muovi delicatamente la pentola senza schiacciare i frutti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Cuoci nello sciroppo"},{"title":"Togli le spezie","content":"Togli la cannella e tutti e 4 i chiodi di garofano a cottura ultimata.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Togli le spezie"},{"title":"Fai raffreddare","content":"Fai raffreddare i fichi nel loro sciroppo in un contenitore basso per non più di 1 ora, poi metti in frigorifero per 4 ore a 4 °C o meno. Non superare 2 ore complessive fuori dal frigorifero.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Fai raffreddare"},{"title":"Servi","content":"Servi 2 fichi a persona con una parte di sciroppo, 20 g di dulce de leche e 30 g di formaggio fresco. Ottieni 6 porzioni.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Servi"}],"notes":"<p>Compra fichi verdi sodi destinati all’alimentazione, non frutti di piante ornamentali. La ricetta si prepara sul fornello: l’acqua bolle vicino a 100 °C al livello del mare e a temperature inferiori in quota. Mantieni i fichi interi. Conserva coperti nello sciroppo a 4 °C o meno fino a 5 giorni e aggiungi formaggio e dulce de leche al servizio. È un dessert da frigorifero, non una conserva da dispensa. Gli accompagnamenti contengono latte.</p>","category":"Dolci","course":"Dolci","cuisine":"Colombiana","difficulty":"Media","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"Nel dulce de breva i fichi restano interi e diventano teneri e lucidi nello sciroppo di panela, cannella e chiodi di garofano. Si accompagnano ad arequipe, il dulce de leche colombiano, e formaggio fresco; la frutta non viene ridotta in confettura.","content_html":"","keywords":["Fichi sciroppati colombiani"],"gallery":[],"public_path":"/it/fichi-sciroppati-colombiani","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Somma dei nutrienti degli ingredienti divisa per le porzioni; stima basata su profili USDA.","note":"Per 2 fichi con un sesto di tutto lo sciroppo, 20 g di dulce de leche e 30 g di queso fresco. La panela è stimata con lo zucchero di canna USDA; sono esclusi spezie rimosse e bicarbonato risciacquato. Lasciare sciroppo riduce lo zucchero consumato."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"ja","slug":"colombia-breva-fig-compote","title":"コロンビア風いちじくのパネラ煮","seo":{"title":"コロンビア風いちじくのパネラ煮","description":"コロンビアの伝統菓子ドゥルセ・デ・ブレバ。かためのいちじくを丸ごと、パネラとシナモン、クローブのシロップでゆっくり煮ます。果実をつぶすいちじくジャムとは異なる、形を残した仕上がりが特徴。ドゥルセ・デ・レチェとフレッシュチーズを添える６人分のレシピです。","faq":[{"q":"いちじくジャムとの違いは？","a":"果実を丸ごとパネラのシロップで煮る料理です。ジャムは切ったりつぶしたりした果実を使う、塗って食べる別のレシピです。"},{"q":"なぜ先に砂糖なしでゆでるのですか？","a":"最初の加熱で柔らかくします。柔らかくなってからシロップに入れると、形を保ちながら中心まで仕上がります。"},{"q":"果実より先にシロップが濃くなったら？","a":"湯を少量ずつ足し、竹串がすっと入るまで弱火で煮続けます。強く混ぜないでください。"}],"author":"Néstor Bastidas","image_alt":"コロンビア風いちじくのパネラ煮","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"ドゥルセ・デ・ブレバは、いちじくを丸ごとパネラ、シナモン、クローブのシロップで煮るコロンビアのお菓子。つやのある柔らかな果実に、アレキペと呼ばれるドゥルセ・デ・レチェとフレッシュチーズを添えます。果実をつぶすジャムとは別の料理です。","ingredients":[{"amount":"600","unit":"g","name":"食用のかための青いいちじく（約12個）"},{"amount":"400","unit":"g","name":"パネラ（未精製のさとうきび糖、細かくしたもの）"},{"amount":"1000","unit":"ml","name":"シロップ用の水"},{"amount":"1500","unit":"ml","name":"下ゆで用の水"},{"amount":"2","unit":"g","name":"食品用の重曹"},{"amount":"1","unit":"本","name":"シナモンスティック（約3 g）"},{"amount":"4","unit":"本","name":"クローブ（ホール、約0.8 g）"},{"amount":"120","unit":"g","name":"アレキペまたはドゥルセ・デ・レチェ"},{"amount":"180","unit":"g","name":"殺菌乳で作ったフレッシュチーズ（ケソ・フレスコ）"}],"steps":[{"title":"いちじくを洗う","content":"いちじく600 gを流水で洗います。傷やかびのないかための果実を選び、熟しすぎて柔らかいものは避けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"いちじくを洗う"},{"title":"切り込みを入れる","content":"各果実の底に深さ約5 mmの浅い十字を入れ、実を割らず丸ごと保ちます。軸の先が硬く突き出ている場合は先端だけ短くします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"切り込みを入れる"},{"title":"いちじくを下ゆでする","content":"水1500 mlと重曹2 gで、静かに沸いてから20〜30分ゆでます。竹串がすっと入る柔らかさが目安です。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"いちじくを下ゆでする"},{"title":"いちじくをすすぐ","content":"ゆでたいちじくをきれいな水ですすぎ、重曹を落とします。シロップに入れる前に水気をよく切った状態にします。"},{"title":"シロップを作る","content":"パネラ400 gを水1000 ml、シナモン1本、クローブ4個とともに弱火で約10分加熱し、溶かします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"シロップを作る"},{"title":"シロップで煮る","content":"丸ごとのいちじくをシロップに入れ、ふたをせず弱火で90〜120分煮ます。色が濃くなってつやが出て、シロップが薄くスプーンを覆えば完成です。果実をつぶさず鍋をそっと揺らします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"シロップで煮る"},{"title":"スパイスを取り出す","content":"煮上がったらシナモンとクローブ4個を取り除きます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"スパイスを取り出す"},{"title":"冷やす","content":"浅い容器でシロップごと1時間以内を目安に冷まし、4 °C以下の冷蔵庫で4時間冷やします。室温に置く時間は合計2時間を超えないようにします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"冷やす"},{"title":"盛り付ける","content":"1人につきいちじく2個とシロップの6分の1量、ドゥルセ・デ・レチェ20 g、チーズ30 gを盛り付けます。6人分です。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"盛り付ける"}],"notes":"<p>観賞用の植物ではなく、食用として販売されているかための青いいちじくを使います。オーブンは使わず、鍋で加熱します。海面付近の水の沸点は約100 °Cで、標高が高いと低くなります。果実は最後まで丸ごと保ちます。シロップに浸してふたをし、4 °C以下で5日以内に食べ切り、チーズとアレキペは食べる直前に添えます。常温保存用の瓶詰めではありません。付け合わせは乳成分を含みます。</p>","category":"デザート","course":"デザート","cuisine":"コロンビア料理","difficulty":"中級","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"ドゥルセ・デ・ブレバは、いちじくを丸ごとパネラ、シナモン、クローブのシロップで煮るコロンビアのお菓子。つやのある柔らかな果実に、アレキペと呼ばれるドゥルセ・デ・レチェとフレッシュチーズを添えます。果実をつぶすジャムとは別の料理です。","content_html":"","keywords":["コロンビア風いちじくのパネラ煮"],"gallery":[],"public_path":"/ja/colombia-breva-fig-compote","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"USDAの食品成分値から材料全量の栄養を合計し、人数分で割った推定値です。","note":"丸ごとのいちじく2個、シロップ全量の6分の1、ドゥルセ・デ・レチェ20 g、ケソ・フレスコ30 gを含む1人分。パネラはUSDAのブラウンシュガーで近似。取り除く香辛料と洗い流す重曹は除外。シロップを残せば糖類の摂取量は減ります。"},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"},{"language":"pt","slug":"doce-de-figo-colombiano","title":"Doce de figo colombiano em calda","seo":{"title":"Doce de figo colombiano em calda","description":"Figos inteiros em calda de panela com canela e cravo, servidos com doce de leite e queijo fresco. Um doce colombiano diferente da geleia de figo.","faq":[{"q":"Qual é a diferença para a geleia de figo?","a":"Os figos ficam inteiros na calda de panela. A geleia leva fruta cortada ou amassada e é feita para passar no pão; são receitas diferentes."},{"q":"Por que cozinhar antes sem panela?","a":"A primeira fervura amacia os figos. Entrar na calda já macios ajuda a preservar o formato sem deixar o centro duro."},{"q":"E se a calda engrossar antes de amaciar?","a":"Adicione água quente aos poucos e continue em fogo baixo até um palito entrar facilmente, sem mexer com força."}],"author":"Néstor Bastidas","image_alt":"Doce de figo colombiano em calda","additional_time_minutes":300,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada-16x9.webp"]},"summary":"No dulce de breva colombiano, os figos permanecem inteiros e ficam macios e brilhantes numa calda de panela, canela e cravo. São servidos com arequipe, o doce de leite colombiano, e queijo fresco; a fruta não é amassada como numa geleia.","ingredients":[{"amount":"600","unit":"g","name":"figos verdes firmes e comestíveis, cerca de 12 frutos"},{"amount":"400","unit":"g","name":"panela ralada, açúcar de cana não refinado"},{"amount":"1000","unit":"ml","name":"água para a calda"},{"amount":"1500","unit":"ml","name":"água para amaciar os figos"},{"amount":"2","unit":"g","name":"bicarbonato de sódio alimentício"},{"amount":"1","unit":"unidade","name":"canela em pau, cerca de 3 g"},{"amount":"4","unit":"unidade","name":"cravos-da-índia inteiros, cerca de 0,8 g"},{"amount":"120","unit":"g","name":"arequipe ou doce de leite"},{"amount":"180","unit":"g","name":"queijo fresco pasteurizado"}],"steps":[{"title":"Lave os figos","content":"Lave os 600 g de figos em água corrente. Escolha frutos firmes, sem machucados ou mofo; evite figos muito maduros e moles.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp","image_alt":"Lave os figos"},{"title":"Marque os figos","content":"Faça uma cruz superficial de cerca de 5 mm na base de cada figo, sem parti-lo. Apare apenas a ponta dura do cabinho se estiver saliente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp","image_alt":"Marque os figos"},{"title":"Amacie os figos","content":"Cozinhe os figos nos 1500 ml de água com os 2 g de bicarbonato por 20–30 minutos a partir da fervura suave, até um palito entrar facilmente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp","image_alt":"Amacie os figos"},{"title":"Enxágue os figos","content":"Enxágue os figos cozidos com água limpa para retirar o bicarbonato. Eles devem estar bem escorridos antes de ir para a calda."},{"title":"Prepare a calda","content":"Dissolva os 400 g de panela nos 1000 ml de água com a canela em pau e os 4 cravos em fogo baixo por cerca de 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp","image_alt":"Prepare a calda"},{"title":"Cozinhe na calda","content":"Cozinhe os figos inteiros destampados na calda em fogo baixo por 90–120 minutos. Estão prontos quando ficam escuros e brilhantes e a calda cobre levemente uma colher; mova a panela com cuidado, sem amassar a fruta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp","image_alt":"Cozinhe na calda"},{"title":"Retire as especiarias","content":"Retire a canela e os 4 cravos ao terminar o cozimento.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp","image_alt":"Retire as especiarias"},{"title":"Esfrie o doce","content":"Esfrie os figos na própria calda num recipiente raso por no máximo 1 hora e leve à geladeira por 4 horas a 4 °C ou menos. Não ultrapasse 2 horas no total fora da geladeira.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp","image_alt":"Esfrie o doce"},{"title":"Sirva","content":"Sirva 2 figos por pessoa com uma parte da calda, 20 g de doce de leite e 30 g de queijo fresco. Rende 6 porções.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp","image_alt":"Sirva"}],"notes":"<p>Compre figos verdes firmes vendidos para consumo, não frutos de plantas ornamentais. A receita é feita no fogão; a água ferve perto de 100 °C ao nível do mar e a temperaturas menores em altitude. Mantenha os frutos inteiros. Guarde tampados na calda a 4 °C ou menos por até 5 dias e acrescente queijo e doce de leite ao servir. É uma sobremesa refrigerada, não uma conserva para guardar no armário. Os acompanhamentos contêm leite.</p>","category":"Sobremesas","course":"Sobremesas","cuisine":"Colombiana","difficulty":"Média","servings":6,"prep_time_minutes":20,"cook_time_minutes":135,"total_time_minutes":455,"excerpt":"No dulce de breva colombiano, os figos permanecem inteiros e ficam macios e brilhantes numa calda de panela, canela e cravo. São servidos com arequipe, o doce de leite colombiano, e queijo fresco; a fruta não é amassada como numa geleia.","content_html":"","keywords":["Doce de figo colombiano em calda"],"gallery":[],"public_path":"/pt/doce-de-figo-colombiano","nutrition":{"calories":480.0,"protein_g":7.6,"carbs_g":96.5,"fat_g":8.9,"serving_size":"1/6","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Soma dos nutrientes dos ingredientes dividida pelas porções; estimativa com perfis de alimentos do USDA.","note":"Por 2 figos com um sexto de toda a calda, 20 g de doce de leite e 30 g de queijo fresco. A panela é aproximada pelo açúcar mascavo USDA; especiarias retiradas e bicarbonato enxaguado não entram. Deixar calda reduz o açúcar consumido."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]]$content$::jsonb;
 aliases jsonb := $aliases$[{"slug":"leche","alias":"leche entera pasteurizada"},{"slug":"azucar","alias":"azúcar blanca"},{"slug":"arroz","alias":"arroz blanco crudo, lavado"},{"slug":"agua","alias":"agua para remojar el arroz"},{"slug":"brevas","alias":"brevas verdes firmes, unas 12 piezas comestibles"},{"slug":"panela","alias":"panela rallada"},{"slug":"agua","alias":"agua para el almíbar"},{"slug":"agua","alias":"agua para ablandar las brevas"},{"slug":"bicarbonato-de-sodio","alias":"bicarbonato de sodio alimentario"},{"slug":"canela-en-rama","alias":"canela en rama, unos 3 g"},{"slug":"clavo-de-olor","alias":"clavos de olor enteros, unos 0,8 g"},{"slug":"arequipe","alias":"arequipe"},{"slug":"queso-fresco","alias":"queso fresco pasteurizado"}]$aliases$::jsonb;
 payload jsonb; v_source uuid; v_group uuid; v_alias jsonb; v_id uuid; v_n integer; promotion record;
BEGIN
 FOR payload IN SELECT x FROM jsonb_array_elements(bundles) x LOOP
 IF EXISTS (SELECT 1 FROM public.recipes WHERE slug IN (SELECT x->>'slug' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) THEN RAISE EXCEPTION 'A recipe or route already exists'; END IF;
 END LOOP;
 FOR promotion IN SELECT * FROM (VALUES
 ('5e41b31b-56d6-4142-ad43-81bf75b6e5f9'::uuid,'canela-en-rama','Canela en rama'),
 ('eebc3525-b7d8-4a4a-a167-39dbb7002d55'::uuid,'panela','Panela'),
 ('c48724fd-3301-4894-a2bf-07dd425b70f4'::uuid,'arequipe','Arequipe'),
 ('2bfedeab-c898-4102-8f07-cfad1ee0a8ba'::uuid,'queso-fresco','Queso fresco')) p(id,slug,name) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredients i WHERE i.slug=promotion.slug AND i.id<>promotion.id) THEN RAISE EXCEPTION 'Canonical identity collision'; END IF;
 UPDATE public.ingredients i SET slug=promotion.slug,name=promotion.name,normalized_name=lower(promotion.name),status='canonical',searchable=true,indexable=false WHERE i.id=promotion.id AND i.status IN ('pending','review');
 END LOOP;
 INSERT INTO public.ingredients(name,normalized_name,slug,description,status,searchable,indexable)
 SELECT 'Brevas','brevas','brevas','Brevas verdes firmes aptas para consumo, utilizadas enteras en almíbar.','canonical',true,false
 WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug='brevas');
 FOR v_alias IN SELECT x FROM jsonb_array_elements(aliases) x LOOP
 SELECT id INTO STRICT v_id FROM public.ingredients WHERE slug=v_alias->>'slug' AND status='canonical' AND searchable;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases a JOIN public.ingredients i ON i.id=a.ingredient_id WHERE a.normalized_alias=lower(v_alias->>'alias') AND a.ingredient_id<>v_id AND i.status='canonical') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) VALUES(v_id,v_alias->>'alias',lower(v_alias->>'alias')) ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
 END LOOP;
 FOR payload IN SELECT x FROM jsonb_array_elements(bundles) x LOOP
 INSERT INTO public.recipes(language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language='es'
 RETURNING id,recipe_group_id INTO v_source,v_group;
 INSERT INTO public.recipes(recipe_group_id,language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT v_group,s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=v_source)<>jsonb_array_length(payload->0->'ingredients') OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=v_source) THEN RAISE EXCEPTION 'Ingredient mapping incomplete'; END IF;
 UPDATE public.recipes SET published=true,editorial_status='published',ready_at=coalesce(ready_at,now()) WHERE recipe_group_id=v_group;
 SELECT count(DISTINCT language) INTO v_n FROM public.recipes WHERE recipe_group_id=v_group AND published AND nutrition IS NOT NULL AND jsonb_array_length(steps)=9;
 IF v_n<>7 THEN RAISE EXCEPTION 'Incomplete seven-language publication'; END IF;
 RAISE NOTICE 'Published group % with seven languages and nine steps',v_group;
 END LOOP;
END $publish$;
COMMIT;
